import type { NodePgDatabase } from "drizzle-orm/node-postgres";

import { db } from "@/lib/db";
import { type schema, sightings } from "@/lib/db/schema";
import {
  type CreateSighting,
  type CreateSightingInput,
  type CreateSightingResult,
  SAVE_FAILURE_MESSAGE,
} from "@/lib/sightings";

type Database = NodePgDatabase<typeof schema>;

export function createSightingOperations(database: Database): {
  create: CreateSighting;
} {
  return {
    create: async (
      input: CreateSightingInput
    ): Promise<CreateSightingResult> => {
      try {
        const [record] = await database
          .insert(sightings)
          .values(input)
          .returning();

        if (!record) {
          return { message: SAVE_FAILURE_MESSAGE, ok: false };
        }

        return { ok: true, sighting: record };
      } catch {
        return { message: SAVE_FAILURE_MESSAGE, ok: false };
      }
    },
  };
}

export const sightingOperations = createSightingOperations(db);
import { z } from "zod";

export const DONENESS_VALUES = ["light", "medium", "dark"] as const;
export type Doneness = (typeof DONENESS_VALUES)[number];

export const createSightingInputSchema = z.object({
  labelDate: z.iso.date(),
  labelMinute: z.int().min(0).max(1439),
});

export type CreateSightingInput = z.infer<typeof createSightingInputSchema>;

// biome-ignore lint/style/useConsistentTypeDefinitions: AGENTS.md prefers types unless extending.
export type Sighting = {
  createdAt: Date;
  doneness: Doneness | null;
  id: number;
  labelDate: string;
  labelMinute: number;
  updatedAt: Date;
};

export type CreateSightingResult =
  | { ok: true; sighting: Sighting }
  | { message: string; ok: false };

export type CreateSighting = (
  input: CreateSightingInput
) => Promise<CreateSightingResult>;

export const SAVE_FAILURE_MESSAGE =
  "Unable to save label time. Check your connection and try again.";
import { desc, sql } from "drizzle-orm";
import {
  check,
  date,
  index,
  integer,
  pgTable,
  smallint,
  text,
  timestamp,
} from "drizzle-orm/pg-core";

import { DONENESS_VALUES } from "@/lib/sightings";

const DONENESS_CONSTRAINT_VALUES = sql.raw(
  DONENESS_VALUES.map((value) => `'${value}'`).join(", ")
);

export const sightings = pgTable(
  "sightings",
  {
    id: integer().primaryKey().generatedAlwaysAsIdentity(),
    labelDate: date("label_date", { mode: "string" }).notNull(),
    labelMinute: smallint("label_minute").notNull(),
    doneness: text({ enum: DONENESS_VALUES }),
    createdAt: timestamp("created_at", { withTimezone: true })
      .defaultNow()
      .notNull(),
    updatedAt: timestamp("updated_at", { withTimezone: true })
      .defaultNow()
      .$onUpdate(() => new Date())
      .notNull(),
  },
  (table) => [
    check(
      "sightings_label_minute_check",
      sql`${table.labelMinute} between 0 and 1439`
    ),
    check(
      "sightings_doneness_check",
      sql`${table.doneness} in (${DONENESS_CONSTRAINT_VALUES})`
    ),
    index("sightings_recent_idx").on(desc(table.createdAt), desc(table.id)),
  ]
);

export const schema = { sightings };

export type Sighting = typeof sightings.$inferSelect;

